using namespace std;

namespace
{
	int n, calls;
	string truth;
	vector<string> report;

	void fail(const string &s)
	{
		throw runtime_error(s);
	}
}

vector<int> query(vector<int> a)
{
	if ((int)a.size() != n)
		fail("query vector length is not n");
	if (++calls > 100)
		fail("more than 100 queries");
	vector<int> b(n, -1), vis(n);
	for (int i = 0; i < n; ++i)
	{
		if (a[i] == -1)
			continue;
		if (a[i] < 0 || a[i] >= n)
			fail("query target out of range");
		if (vis[a[i]]++)
			fail("a non-idle target is used more than once");
		b[i] = report[i][a[i]] - '0';
	}
	return b;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int c, t, mx = 0;
	if (!(cin >> c >> t) || c < 1 || c > 2 || t < 1 || t > 1000)
	{
		cerr << "Invalid judge input: expected c in {1,2}, 1 <= T <= 1000" << endl;
		return 2;
	}
	for (int test = 1; test <= t; ++test)
	{
		if (!(cin >> n >> truth) || n < 3 || n > 100 || (int)truth.size() != n || truth.find_first_not_of("01") != string::npos)
		{
			cerr << "Invalid judge input on test " << test << endl;
			return 2;
		}
		if (count(truth.begin(), truth.end(), '1') <= n / 2 || (c == 1 && truth[0] != '1'))
		{
			cerr << "Invalid judge input: majority or subtask condition violated" << endl;
			return 2;
		}
		report.assign(n, "");
		for (int i = 0; i < n; ++i)
		{
			if (!(cin >> report[i]) || (int)report[i].size() != n || report[i].find_first_not_of("01") != string::npos || (truth[i] == '1' && report[i] != truth))
			{
				cerr << "Invalid judge input: malformed or inaccurate good-machine report" << endl;
				return 2;
			}
		}
