#include "period.h"
#include <bits/stdc++.h>

using namespace std;

namespace
{
	int n, q, calls;
	string s;
	vector<int> z;

	void fail(const string &s)
	{
		throw runtime_error(s);
	}
}

int query(int i)
{
	if (i < 0 || i >= n)
		fail("query index out of range");
	if (++calls > q)
		fail("query budget exceeded");
	return z[i];
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	if (!(cin >> n >> q >> s) || n < 1 || n > 1000000 || q < 0 || q > n || (int)s.size() != n || s.find_first_not_of("abcdefghijklmnopqrstuvwxyz") != string::npos)
	{
		cerr << "Invalid judge input: expected n, q and a lowercase string of length n" << endl;
		return 2;
	}
	z.assign(n, 0);
	z[0] = n;
	for (int i = 1, l = 0, r = 0; i < n; ++i)
	{
		if (i <= r)
			z[i] = min(z[i - l], r - i + 1);
		while (i + z[i] < n && s[z[i]] == s[i + z[i]])
			++z[i];
		if (i + z[i] - 1 > r)
			l = i, r = i + z[i] - 1;
	}
	int expected = 1;
	for (int d = 1; d < n; ++d)
		if (n % d == 0 && z[d] == n - d)
		{
			expected = n / d;
			break;
		}
	try
	{
		int ans = solve(n, q);
		if (ans != expected)
			fail("expected " + to_string(expected) + ", got " + to_string(ans));
		cout << "Correct! Answer: " << ans << ", queries used: " << calls << '/' << q << endl;
	}
	catch (const exception &e)
	{
		cout << "Wrong answer: " << e.what() << endl;
		return 1;
	}
	return 0;
}

